const assert = require('node:assert/strict');
const fs = require('node:fs');
const vm = require('node:vm');
const { JSDOM } = require('jsdom');
const dom = new JSDOM('<input id="query"><div id="results" class="hidden"><div class="loading-indicator hidden"></div><div class="quick-search-results-container"></div></div><button id="outside"></button>');
const $ = require('jquery')(dom.window);
const handlers = new Map();
const hooks = { on(name, callback) { handlers.set(name, callback); }, fire() {} };
let search;
const context = {
  $, document: dom.window.document,
  config: { searchEnabled: true },
  app: { user: { privileges: { 'search:content': true } }, parseAndTranslate(name, data, callback) {
    callback($('<ul id="quick-search-results"><li><a href="#">Result</a></li></ul>'));
  } },
  ajaxify: { data: { template: {} } },
  utils: { debounce: fn => fn },
  define(name, deps, factory) { search = factory({}, {}, hooks, {}, {}); },
};
vm.runInNewContext(fs.readFileSync('public/src/modules/search.js', 'utf8'), context);
const input = $('#query').val('first query');
