input.val('second query').trigger('refresh');
assert.equal(responses.length, 1);
handlers.get('action:ajaxify.end')();
responses.shift()({ posts: [] });
assert.equal(results.find('#quick-search-results').length, 0, 'late response cannot restore stale results');
console.log('quick search focus and navigation checks passed');
